raw:
{
  "entity_types": [
    {
      "name": "School",
      "domain": "1. Institution structure",
      "definition": "A top-level degree-granting university in Gemiverse (starting with New York University and Columbia University).",
      "sample_evidence": "Evidenced across all 15 sample pages (nyu-01 through nyu-17 for New York University; col-01 through col-07 for Columbia University).",
      "fields": [
        {
          "name": "id",
          "type": "string",
          "required": true,
          "how_verified": "Canonical slug (e.g., 'nyu', 'columbia') matched 1-to-1 against the verified institutional root .edu domain."
        },
        {
          "name": "official_name",
          "type": "string",
          "required": true,
          "how_verified": "Exact legal charter name verified verbatim in the root .edu institutional footer or registrar masthead (e.g., 'New York University' in nyu-01)."
        },
        {
          "name": "primary_domain",
          "type": "domain",
          "required": true,
          "how_verified": "EDUCAUSE .edu registry check and HTTPS TLS certificate validation (nyu.edu, columbia.edu)."
        },
        {
          "name": "academic_calendar_url",
          "type": "url",
          "required": true,
          "how_verified": "HTTP 200 check under primary_domain registrar subdomain containing machine-parseable term start and end dates."
        }
      ]
    },
    {
      "name": "AcademicUnit",
      "domain": "1. Institution structure",
      "definition": "A formal college, school-level division, or academic department within a School that administers programs, courses, or research institutes.",
      "sample_evidence": "Colleges/divisions evidenced in nyu-02 and nyu-17 ('NYU Steinhardt'), nyu-04 ('NYU Tandon School of Engineering'), and col-07 ('Columbia College', 'Columbia Engineering'). Department evidenced in nyu-02 ('Music and Performing Arts Professions').",
      "fields": [
        {
          "name": "id",
          "type": "string",
          "required": true,
          "how_verified": "Scoped slug (e.g., 'nyu:steinhardt', 'nyu:steinhardt:mpap') checked against the School's official academic units directory."
        },
        {
          "name": "name",
          "type": "string",
          "required": true,
          "how_verified": "Verbatim unit title checked against the unit masthead or official academic bulletin."
        },
        {
          "name": "unit_kind",
          "type": "enum[college_or_division, department]",
          "required": true,
          "how_verified": "Checked against the university governance/academic structure page (whether it is a degree-recommending school/college vs. a department housed inside one)."
        },
        {
          "name": "official_url",
          "type": "url",
          "required": true,
          "how_verified": "HTTP 200 URL resolving under the parent School's primary_domain (e.g., engineering.nyu.edu in nyu-04)."
        },
        {
          "name": "role_contact_email",
          "type": "email",
          "required": false,
          "how_verified": "Must match an institutional role/shared mailbox pattern under primary_domain (e.g., 'mpap-concertmusic@nyu.edu' in nyu-02) and pass a negative regex/directory filter rejecting personal NetID/UNI addresses."
        }
      ]
    },
    {
      "name": "Program",
      "domain": "1. Institution structure",
      "definition": "A formal degree track, major, minor, or academic concentration offered by an AcademicUnit.",
      "sample_evidence": "Partial evidence in nyu-02 under 'Related Programs: Concert Composition'. Evidence gap: undergraduate majors, degree credential codes (BA/BS/BM/PhD), and degree requirement trees do not appear in these event-only samples.",
      "fields": [
        {
          "name": "id",
          "type": "string",
          "required": true,
          "how_verified": "Scoped slug matched to an entry in the official university academic bulletin."
        },
        {
          "name": "name",
          "type": "string",
          "required": true,
          "how_verified": "Exact program name verified on the official academic bulletin or department Programs index (e.g., 'Concert Composition' in nyu-02)."
        },
        {
          "name": "credential_type",
          "type": "enum[major, minor, concentration, masters, doctoral, certificate]",
          "required": true,
          "how_verified": "Verified against official registrar/bulletin degree inventory; cannot be inferred from an event blurb alone (nyu-02 requires a bulletin fetch before committing credential_type)."
        },
        {
          "name": "scope_summary",
          "type": "string",
          "required": true,
          "how_verified": "One-sentence factual summary of subject matter extracted from the official program page (<= 240 chars), verified free of faculty names or rankings."
        },
        {
          "name": "bulletin_url",
          "type": "url",
          "required": true,
          "how_verified": "HTTP 200 URL on the official university bulletin or department program page."
        }
      ]
    },
    {
      "name": "Campus",
      "domain": "2. Space",
      "definition": "A named geographic campus district operated by a School.",
      "sample_evidence": "Explicitly tagged in col-01 and col-07 ('Manhattanville'); evidenced via campus map references and street addresses in nyu-04 ('370 Jay St, Brooklyn'), nyu-02/nyu-07/nyu-15 (Washington Square area), and col-05 ('420 W. 118 St.', Morningside Heights).",
      "fields": [
        {
          "name": "id",
          "type": "string",
          "required": true,
          "how_verified": "Scoped slug (e.g., 'columbia:manhattanville', 'nyu:brooklyn', 'nyu:washington-square') matched against the official university campus map index."
        },
        {
          "name": "name",
          "type": "string",
          "required": true,
          "how_verified": "Official district name verified on the School's campus map page or structured location alias (e.g., '/Location/Manhattanville' in col-01)."
        },
        {
          "name": "municipality",
          "type": "string",
          "required": true,
          "how_verified": "Borough/city and state verified against official campus map addresses ('Brooklyn, NY' in nyu-04; 'New York, NY' in col-01)."
        },
        {
          "name": "centroid",
          "type": "lat_lon",
          "required": true,
          "how_verified": "Latitude/longitude verified to lie inside the official campus map polygon."
        }
      ]
    },
    {
      "name": "Building",
      "domain": "2. Space",
      "definition": "A physical university structure identified by a street address that contains indoor Venues or hosts Services and Events.",
      "sample_evidence": "Strongly evidenced: Paulson Center / 181 Mercer St (nyu-02), 370 Jay St (nyu-04), 20 Cooper Square (nyu-05), Bobst Library (nyu-07/10/14), 196 Mercer St (nyu-09), Bern Dibner Library (nyu-12), Pless Hall (nyu-17), Jerome L. Greene Science Center / 605 W 129th St (col-01), International Affairs Building / 420 W 118th St (col-05), The Forum / 601 W 125th St (col-07). Evidence gap: standing turnstile hours are only indirectly hinted via visitor notes (nyu-04).",
      "fields": [
        {
          "name": "id",
          "type": "string",
          "required": true,
          "how_verified": "Scoped slug matched to official campus facilities/map building code or location_id."
        },
        {
          "name": "name",
          "type": "string",
          "required": true,
          "how_verified": "Canonical building title verified against the official campus map directory."
        },
        {
          "name": "street_address",
          "type": "string",
          "required": true,
          "how_verified": "Normalized street address checked against campus facilities listing and NYC GeoSearch/USPS."
        },
        {
          "name": "coordinates",
          "type": "lat_lon",
          "required": true,
          "how_verified": "Verified from structured feed coordinates (e.g., '40.728, -73.9914' in nyu-05) or campus GIS within 50 meters of street_address."
        },
        {
          "name": "access_policy",
          "type": "enum[public_lobby, campus_id_required, guest_preregistration_allowed, unknown]",
          "required": true,
          "how_verified": "Checked against official public safety/visitor access pages (e.g., nyu-04 states external guests require advance registration for 370 Jay St access; defaults to 'unknown' if unstated)."
        }
      ]
    },
    {
      "name": "Venue",
      "domain": "2. Space",
      "definition": "A specific usable indoor space (room, auditorium, lounge, makerspace/lab) inside a Building, or a named outdoor place on a Campus, annotated with checkable affordances.",
      "sample_evidence": "Indoor venues evidenced in nyu-02 (Room 570), nyu-04 (Room 1201, 12th Floor), nyu-07/10/14 (Bobst Rm 619, 743, 745), nyu-09 (IHDSC Seminar Room, 8th Floor), nyu-12 (Dibner LC 400), nyu-17 (First Floor Lounge, Pless Hall), col-01 (Ground Floor), col-05 (Lehman Suite, IAB Room 406). Outdoor place evidenced in nyu-15 ('Sasaki Garden', location_id 10342). Evidence gap: standing daily room affordances (quiet study rules, permanent tools, everyday open hours) have no dedicated space-directory pages in these event-only samples.",
      "fields": [
        {
          "name": "id",
          "type": "string",
          "required": true,
          "how_verified": "Scoped slug or feed location_id (e.g., '10342' for Sasaki Garden in nyu-15; 'nyu:bobst:rm-743')."
        },
        {
          "name": "name",
          "type": "string",
          "required": true,
          "how_verified": "Exact room number, suite name, or outdoor place name verified in room directory or event feed."
        },
        {
          "name": "venue_kind",
          "type": "enum[classroom_seminar, auditorium_stage, study_space, lounge_commons, lab_makerspace, outdoor_place]",
          "required": true,
          "how_verified": "Verified against official library/registrar/facilities space classification (e.g., 'First Floor Lounge' -> lounge_commons in nyu-17; 'Sasaki Garden' -> outdoor_place in nyu-15)."
        },
        {
          "name": "floor_or_wayfinding",
          "type": "string",
          "required": false,
          "how_verified": "Floor designation or entry gate directions verified verbatim from source ('12th Floor' in nyu-04; 'Enter Sasaki Garden via 1-2 Washington Square Village on West 3rd Street' in nyu-15)."
        },
        {
          "name": "coordinates",
          "type": "lat_lon",
          "required": false,
          "how_verified": "Required when venue_kind='outdoor_place' and verified against feed/map GIS ('40.728115, -73.996917' in nyu-15); omitted for indoor rooms that inherit Building.coordinates."
        },
        {
          "name": "affordances",
          "type": "array[affordance_id]",
          "required": true,
          "how_verified": "Controlled IDs from affordances list verified ONLY from standing space/library/facilities pages (never permanently inferred from a one-off event's catering or temporary cushions; empty array [] permitted until verified)."
        },
        {
          "name": "reservable_by_students",
          "type": "boolean",
          "required": false,
          "how_verified": "Checked against institutional room booking portals (e.g., LibCal Spaces / EMS)."
        }
      ]
    },
    {
      "name": "Event",
      "domain": "3. Development resources",
      "definition": "A scheduled, time-bounded live happening—such as a workshop, lecture, performance, study break, competition showcase, or market.",
      "sample_evidence": "Directly evidenced in all 15 sample pages across both NYU and Columbia.",
      "fields": [
        {
          "name": "id",
          "type": "string",
          "required": true,
          "how_verified": "Source feed primary key or GUID (e.g., '412484' in nyu-05; 'CAL-00bbdb7c-...' in col-01) or deterministic URL+start hash for static pages."
        },
        {
          "name": "title",
          "type": "string",
          "required": true,
          "how_verified": "Verbatim title from structured JSON 'title'/'summary' or HTML <h1>. Public work/talk titles are preserved solely as opaque event identifiers, never parsed into speaker attributes."
        },
        {
          "name": "event_kind",
          "type": "enum[workshop, talk_panel, performance_exhibit, social_study_break, competition_showcase, market_fair, community_wellness]",
          "required": true,
          "how_verified": "Mapped deterministically from source event_type tags ('Lecture / Panel' in nyu-04; 'Reference Services workshops' in nyu-07) plus structural description cues."
        },
        {
          "name": "occurrences",
          "type": "array[object{start_iso, end_iso_or_null}]",
          "required": true,
          "how_verified": "ISO-8601 timestamps with timezone verified against JSON UTC/ISO fields (nyu-05, col-01) or linked .ics files (nyu-01). Supports multi-performance runs (nyu-01, col-07) and null end times when omitted by source (nyu-15). Pages missing an explicit year in HTML prose (nyu-02, nyu-17) must verify year via .ics or feed metadata before admission."
        },
        {
          "name": "delivery_mode",
          "type": "enum[in_person, online, hybrid]",
          "required": true,
          "how_verified": "Cross-checked between location fields and online meeting URLs. If a page declares 'In-Person' with a physical room while also printing 'Please note this is an online event' (nyu-07, nyu-10, nyu-12), checker inspects the .ics LOCATION field; if unresolved, event is quarantined rather than guessed."
        },
        {
          "name": "cost_type",
          "type": "enum[free, paid_ticketed, unknown]",
          "required": true,
          "how_verified": "Verified from explicit Cost field ('Free' in nyu-02/05/17) or ticketing link ('Get Tickets' without price in nyu-01 -> 'unknown' or verified via linked box-office page)."
        },
        {
          "name": "registration_rule",
          "type": "enum[none, encouraged, required, ticketed, external_guests_only]",
          "required": true,
          "how_verified": "Verified against explicit registration prose ('No Registration Necessary' in nyu-17; 'not required but encouraged' in nyu-14; 'Registration is required' in nyu-02; external-guest Luma requirement in nyu-04)."
        },
        {
          "name": "eligibility",
          "type": "enum[public, campus_community_only, students_only, k12_family_oriented]",
          "required": true,
          "how_verified": "Checked against Audience/Open To fields and body restrictions ('open only to the NYU community' in nyu-12; 'Open to the Public' in nyu-04/15; 'for kids of all ages' -> k12_family_oriented in col-01)."
        },
        {
          "name": "summary",
          "type": "string",
          "required": true,
          "how_verified": "Factual <= 280-char distillation of source description checked by a PII/person-scrubber to ensure zero speaker bios, organizer names, or personal emails/phones remain."
        },
        {
          "name": "action_url",
          "type": "url",
          "required": true,
          "how_verified": "Canonical event webpage or official registration link (e.g., Zoom registration in col-03, Luma link in nyu-04) returning HTTP 200."
        },
        {
          "name": "affordances",
          "type": "array[affordance_id]",
          "required": true,
          "how_verified": "Controlled IDs verified from explicit activity cues in the event text (e.g., vegan/GF pizza and crafts in nyu-10 -> food_and_refueling, making_things)."
        }
      ]
    },
    {
      "name": "Course",
      "domain": "3. Development resources",
      "definition": "A credit-bearing or official registrar-listed course offered in a specific academic term by an AcademicUnit.",
      "sample_evidence": "No evidence yet in sample pages (note: nyu-12 uses the LibCal label 'Dibner Library classes' for a competition showcase, which checkers explicitly reject as a registrar Course).",
      "fields": [
        {
          "name": "id",
          "type": "string",
          "required": true,
          "how_verified": "Scoped subject-number-term key (e.g., 'columbia:COMS-W4111:2026-fall') verified in NYU Albert public search or Columbia Directory of Classes."
        },
        {
          "name": "course_code",
          "type": "string",
          "required": true,
          "how_verified": "Official registrar subject and catalog number verified verbatim."
        },
        {
          "name": "title",
          "type": "string",
          "required": true,
          "how_verified": "Official registrar course title."
        },
        {
          "name": "term",
          "type": "string",
          "required": true,
          "how_verified": "Term identifier verified against active registrar term schedule."
        },
        {
          "name": "credits",
          "type": "number",
          "required": true,
          "how_verified": "Point/credit value verified against official bulletin/registrar feed."
        },
        {
          "name": "prerequisites_text",
          "type": "string",
          "required": false,
          "how_verified": "Verbatim course-code prerequisites from official bulletin (stripped of any 'permission of Prof. X' person names, normalized to 'instructor/department permission')."
        },
        {
          "name": "catalog_url",
          "type": "url",
          "required": true,
          "how_verified": "HTTP 200 URL on the official .edu course catalog or bulletin."
        }
      ]
    },
    {
      "name": "Opportunity",
      "domain": "3. Development resources",
      "definition": "A structured, non-course growth opening with eligibility or application mechanics—covering research openings, competitions, funding/grants, student jobs, and structured mentorship programs (never individual person profiles).",
      "sample_evidence": "Competition and prize funding indirectly evidenced in nyu-12 ('Hack Dibner is an annual semester-long proof-of-concept competition... First place receives $700 and the runner up receives $300'). Evidence gap: standalone open calls for research_opening, funding grants, campus jobs, and mentorship cohorts do not appear directly in the 15 samples.",
      "fields": [
        {
          "name": "id",
          "type": "string",
          "required": true,
          "how_verified": "Scoped slug or official portal posting ID."
        },
        {
          "name": "title",
          "type": "string",
          "required": true,
          "how_verified": "Official program/opening title verified on the hosting unit's call page ('Hack Dibner' in nyu-12)."
        },
        {
          "name": "opportunity_kind",
          "type": "enum[research_opening, competition, funding, job, mentorship]",
          "required": true,
          "how_verified": "Checked against official program terms (e.g., prize contest -> competition; cohort/office advising program -> mentorship; lab RA posting -> research_opening)."
        },
        {
          "name": "status",
          "type": "enum[upcoming, open, closed]",
          "required": true,
          "how_verified": "Computed deterministically by comparing current UTC time against published open/deadline dates and checking page for 'applications closed' banners (e.g., nyu-12 Final Showcase implies fall cohort applications are 'closed')."
        },
        {
          "name": "deadline_iso",
          "type": "iso_datetime",
          "required": false,
          "how_verified": "Application or submission deadline verified verbatim on the official call page."
        },
        {
          "name": "compensation_or_award",
          "type": "string",
          "required": false,
          "how_verified": "Verbatim stipend, NYC pay-transparency wage range, grant cap, or prize amounts ('$700 first place, $300 runner up' in nyu-12)."
        },
        {
          "name": "eligibility_criteria",
          "type": "string",
          "required": true,
          "how_verified": "Checkable institutional rules (school, degree level, enrollment status) extracted from official call."
        },
        {
          "name": "commitment_summary",
          "type": "string",
          "required": false,
          "how_verified": "Duration or weekly hours checked against posting ('semester-long' in nyu-12)."
        },
        {
          "name": "apply_url",
          "type": "url",
          "required": true,
          "how_verified": "HTTP 200 URL on official .edu or institution-delegated application portal."
        }
      ]
    },
    {
      "name": "Service",
      "domain": "3. Development resources",
      "definition": "A standing institutional support resource, advising/help desk, accessibility accommodation channel, equipment lending desk, or evergreen guide available continuously across a term.",
      "sample_evidence": "Indirectly evidenced via embedded links and support blocks: LibGuides ('Finals Resources' in nyu-10, 'Hack Dibner' guide in nyu-12, 'NYU Welcome: The Libraries' in nyu-14), library help channels ('lib-reference@nyu.edu' in nyu-07/10, 'zotero-help@library.columbia.edu' in col-03), and disability accommodation services (nyu-01/02/07/17). Evidence gap: standalone service homepages (counseling, career center, makerspace tool checkout, peer advising hubs) are not directly included in the samples.",
      "fields": [
        {
          "name": "id",
          "type": "string",
          "required": true,
          "how_verified": "Scoped slug matched to the hosting office/library service directory."
        },
        {
          "name": "name",
          "type": "string",
          "required": true,
          "how_verified": "Official service or guide title verified on unit page, stripped of personal author credits (e.g., 'Finals Resources' from 'Finals Resources by Laurie Murphy' in nyu-10)."
        },
        {
          "name": "service_kind",
          "type": "enum[academic_research_help, career_advising, wellbeing_accessibility, curated_guide, equipment_making_access, peer_mentoring_desk]",
          "required": true,
          "how_verified": "Checked against hosting office mandate and explicit service offerings."
        },
        {
          "name": "access_method",
          "type": "enum[walk_in, appointment, online_self_serve, role_email_request]",
          "required": true,
          "how_verified": "Verified from explicit access instructions (e.g., 'submit your request at least two weeks before' via role email in nyu-02 -> role_email_request; LibGuide URL -> online_self_serve)."
        },
        {
          "name": "hours_summary",
          "type": "string",
          "required": false,
          "how_verified": "Standing operating hours verified against official service hours widget."
        },
        {
          "name": "role_contact_channel",
          "type": "string",
          "required": false,
          "how_verified": "Verified institutional role email or helpdesk URL ('zotero-help@library.columbia.edu' in col-03; 'lib-reference@nyu.edu' in nyu-07)."
        },
        {
          "name": "service_url",
          "type": "url",
          "required": true,
          "how_verified": "HTTP 200 URL under .edu or official library LibGuides domain."
        },
        {
          "name": "affordances",
          "type": "array[affordance_id]",
          "required": true,
          "how_verified": "Controlled IDs verified from explicit service capabilities."
        }
      ]
    },
    {
      "name": "GrowthNeed",
      "domain": "4. Student growth needs",
      "definition": "A canonical, impersonal node in the shared student growth taxonomy against which Venues, Events, Courses, Opportunities, and Services are tagged. Never stores or points to any student.",
      "sample_evidence": "Surface institutional category tags appear in nyu-07 ('Research Readiness') and nyu-10 ('Creativity and Wellbeing in Research'); the unified 11-need cross-campus taxonomy is schema-governed.",
      "fields": [
        {
          "name": "id",
          "type": "string",
          "required": true,
          "how_verified": "Exact membership in the canonical need_taxonomy enum."
        },
        {
          "name": "label",
          "type": "string",
          "required": true,
          "how_verified": "Exact match against schema governance specification."
        },
        {
          "name": "one_line_definition",
          "type": "string",
          "required": true,
          "how_verified": "Exact match against schema governance specification; audited to contain zero person-level fields."
        },
        {
          "name": "public_page_signals",
          "type": "array[string]",
          "required": true,
          "how_verified": "Auditable lexical/structural patterns checked against labeled campus pages for tagging precision."
        }
      ]
    },
    {
      "name": "Organisation",
      "domain": "5. Organisations",
      "definition": "A collective actor operating on or with campus—a student club or collective, research lab/center/institute, university office/library, or verified external partner.",
      "sample_evidence": "Richly evidenced: student/grad collectives & outreach clubs ('Nevermind the Noise' in nyu-02; 'CUNO / Columbia University Neuroscience Outreach' in col-01); labs/centers/institutes ('CUSP' in nyu-04, 'Berkley Institute' in nyu-05, 'CRACS Co-Lab' and 'IHDSC' in nyu-09, 'Zuckerman/zmbbi' in col-01, 'Lehman Center for American History' in col-05); campus offices/libraries ('NYU Libraries' in nyu-07/10/14, 'Bern Dibner Library' in nyu-12, 'Office of Sustainability' in nyu-14, 'Faculty Housing and Residential Services' in nyu-15, 'NYU Steinhardt Office of Student Affairs' in nyu-17, 'Columbia Libraries' in col-03); external partners ('Brennan Center for Justice' and 'Federal Election Commission' in nyu-05, 'BioBus' in col-01). Evidence gap: student-activities registry pages (NYU Engage / Columbia LionLink) with club charters and meeting cadences are not in the samples.",
      "fields": [
        {
          "name": "id",
          "type": "string",
          "required": true,
          "how_verified": "Scoped slug or feed group ID (e.g., LiveWhale 'gid: 347' in nyu-05, 'gid: 26' in nyu-15, Bedework 'agrp_calsuite-zmbbi' in col-01)."
        },
        {
          "name": "name",
          "type": "string",
          "required": true,
          "how_verified": "Official organisation name checked against feed group_title, club registry, or institutional masthead."
        },
        {
          "name": "org_kind",
          "type": "enum[student_club_collective, lab_center_institute, campus_office_library, external_partner]",
          "required": true,
          "how_verified": "Verified by checking membership in official student club directory vs. research centers directory vs. administrative units vs. non-.edu external entity."
        },
        {
          "name": "mission_summary",
          "type": "string",
          "required": false,
          "how_verified": "One-sentence impersonal mission extracted from official 'About' blurb (e.g., Nevermind the Noise description in nyu-02; CUSP blurb in nyu-04), scrubbed of officer/faculty names."
        },
        {
          "name": "official_url",
          "type": "url",
          "required": false,
          "how_verified": "HTTP 200 homepage or official Engage/LionLink profile URL."
        },
        {
          "name": "public_contact_channel",
          "type": "string",
          "required": false,
