  "source_tiers": {
    "principle": "Rather miss than be wrong: omitting an unverified event costs a missed suggestion, whereas asserting a wrong room, wrong date, or wrong delivery mode sends a real student across NYC to an empty room and burns trust.",
    "tiers": [
      {
        "tier": 1,
        "name": "Structured Authoritative Institutional Feeds & Signed Registries",
        "examples_in_samples": [
          "NYU LiveWhale JSON feeds on events.nyu.edu (nyu-05, nyu-15) with UTC timestamps, group IDs, and lat/lon",
          "Columbia Bedework JSON feeds on events.columbia.edu (col-01, col-03, col-05) with GUIDs, UTC dates, and location aliases",
          "Official .ics calendar files hosted on .edu (linked in nyu-01)",
          "Registrar APIs, official campus GIS tables, and .well-known/gemiverse-agents.json manifests"
        ],
        "trust_scope": "Authoritative for canonical IDs, timestamps/timezones, geographic coordinates, institutional hierarchy, and cancellation flags."
      },
      {
        "tier": 2,
        "name": "Official .edu & Delegated Institutional SaaS Web Pages",
        "examples_in_samples": [
          "Static/CMS HTML under *.nyu.edu and *.columbia.edu (nyu-01, nyu-02, nyu-04, nyu-17, col-07)",
          "Institutionally operated LibCal pages on nyu.libcal.com (nyu-07, nyu-09, nyu-10, nyu-12, nyu-14)"
        ],
        "trust_scope": "Trusted for prose summaries, related programs/departments (nyu-02), and room names AFTER passing template-boilerplate contradiction checks."
      },
      {
        "tier": 3,
        "name": "Verified Organisation Agents & Outbound-Linked Operational Pages",
        "examples_in_samples": [
          "External RSVP/ticketing pages explicitly linked from Tier 1/2 .edu pages: Luma (nyu-04), Eventbrite (col-01), Columbia Zoom registration (col-03)",
          "Cryptographically verified public Agents (SPEAKS_FOR an Organisation) answering about their own Organisation's activities"
        ],
        "trust_scope": "Allowed only to enrich operational fields (remaining RSVP slots, external guest rules, club FAQ) on entities already anchored in Tier 1/2, or to publish events exclusively under that verified Organisation. Cannot create or modify School, AcademicUnit, Campus, or Building facts."
      },
      {
        "tier": 4,
        "name": "Unverified Web, Social Media, & Student Gemi Hearsay (Rejected from Base)",
        "examples_in_samples": [
          "Unlinked social posts, flyers, Reddit/Sidechat rumors, or unverified claims from student Gemis"
        ],
        "trust_scope": "Zero write access to the base. At most triggers a background Tier 1/2 URL lookup if an official .edu link is cited."
      }
    ],
    "admission_and_contradiction_rules": [
