  "decisions": [
    {
      "choice_weighed": "One monolithic Resource entity vs. nine micro-types (one per Domain 3 noun) vs. four lifecycle-aligned types (Event, Course, Opportunity, Service).",
      "chosen": "Four lifecycle-aligned types (Event, Course, Opportunity, Service).",
      "why": "Freshness cadences, required checkable fields, and world projections fracture cleanly along these four lifecycles (hourly/daily occurrences for Event, term registrar schedules for Course, deadline/application status for Opportunity, standing access hours for Service) while keeping the entire schema at 13 student-understandable types."
    },
    {
      "choice_weighed": "Representing faculty, speakers, and mentors as limited public Person nodes vs. banning Person nodes altogether in favor of impersonal Opportunity (mentorship), Organisation, Agent, and private name cards.",
      "chosen": "Zero Person nodes or person-describing fields in the base.",
      "why": "Directly honors the non-negotiable privacy rule, avoids stale/defamatory dossiers in a shared decentralized graph, and exploits Gemiverse's P2P architecture where human mentorship connections belong in consenting Gemis' private name cards."
    },
    {
      "choice_weighed": "Tagging Venues directly with GrowthNeeds only vs. introducing observable Affordances between Places/Resources and GrowthNeeds.",
      "chosen": "Two-layer bridge: checkable Affordances (what a student physically/practically does) mapped to GrowthNeeds (why they seek it).",
      "why": "Whether Pless Hall Lounge has snacks and casual seating (nyu-17) or Bobst Rm 745 has meditation cushions (nyu-14) is objectively verifiable on a public source, whereas whether a student uses quiet seating to 'build_a_skill' or 'rest_and_recover' depends on private context."
    },
    {
      "choice_weighed": "Auto-resolving LibCal's 'In-Person + Room' vs. 'Please note this is an online event' footer conflict (nyu-07, nyu-10, nyu-12) by trusting the top header vs. labelling 'hybrid' vs. quarantining until .ics/agent verification.",
      "chosen": "Quarantine conflicting delivery_mode unless deterministically resolved by the Tier 1 .ics payload.",
      "why": "Enforces 'rather miss than be wrong' on high-regret physical logistics; guessing 'hybrid' would invent a nonexistent Zoom link, while blindly trusting headers could break on genuine last-minute moves online."
    },
    {
      "choice_weighed": "Strict Campus -> Building -> Venue three-tier requirement on every location vs. flexible spatial attachment.",
      "chosen": "Allow outdoor Venues directly ON_CAMPUS (Sasaki Garden in nyu-15) and allow LOCATED_AT to target Building directly when no room is stated ('20 Cooper Square' in nyu-05, 'The Forum' in col-07).",
      "why": "Eliminates synthetic placeholder nodes ('Outdoor Building' or 'Unknown Room') so every spatial node corresponds 1-to-1 to a verifiable real-world entity."
    },
    {
      "choice_weighed": "Storing the four shared functional buildings (Library, Clubs, Commons, Career) as synthetic Building rows in the base vs. treating them as deterministic view projections alongside real physical Building landmarks.",
      "chosen": "Pure projection views over Base entities, while Base Building rows store only real brick-and-mortar campus structures.",
      "why": "Preserves strict public-source checkability for all Space entities in the base while giving online workshops (col-03), cross-campus clubs, and non-spatial funding calls a natural spatial home in the UI."
    },
    {
      "choice_weighed": "Allowing k-anonymized Gemi interest/attendance counters into the base to rank 'popular' events vs. keeping the base 100% free of student telemetry.",
      "chosen": "Zero student/Gemi telemetry in the base.",
      "why": "Prevents small-set presence leaks in niche seminars, blocks popularity cascades from burying high-fit niche opportunities ('pick treasure, do not pile up junk'), and keeps base trust purely source-verifiable."
    }
  ],
